/**
 * Error types surfaced by the EDK SDK.
 *
 * Five classes, distinguished by *what* went wrong:
 *
 *   `DeployConfigError`            — misconfiguration detected before any
 *                                    network call (missing client id/secret,
 *                                    bad URL, etc.).
 *   `EdkValidationError`           — author/SDK invariant violation: malformed
 *                                    entity source, unknown parameter, missing
 *                                    required field, etc. Detected at
 *                                    build/serialize time before any HTTP
 *                                    call. Distinct from `DeployError` so
 *                                    callers can branch on type.
 *   `DeployError`                  — the request reached a service and failed;
 *                                    carries the status, response body, and
 *                                    the original AxiosError as `cause` so an
 *                                    agent catching it can diagnose without
 *                                    re-reading the transcript.
 *   `DeployUpdateUnsupportedError` — the entity's hash changed (so an update
 *                                    is required) but the backend has no PUT
 *                                    path for this entity kind yet (skills,
 *                                    flows). Carries the recorded id so the
 *                                    operator can locate and delete it on the
 *                                    platform, then re-run.
 *   `DeployStateCorruptError`      — `.edk-state/<appId>.json` exists but does
 *                                    not parse to the supported schema. The
 *                                    SDK never silently rebuilds — the
 *                                    operator must run the import CLI to
 *                                    regenerate state from the server.
 *
 * **Convention for new throws:** anywhere SDK code throws because of an
 * agent's invalid input or a config-time invariant violation, throw
 * `EdkValidationError` (not plain `Error`/`TypeError`). This keeps
 * `.message` consistently surfaced by SDK error renderers / agent catch
 * handlers, and lets callers branch on `instanceof EdkValidationError`
 * vs `DeployError` if they want different recovery paths. Reserve plain
 * `Error` for genuinely-internal invariants the agent can't fix
 * (cycle detection, "unreachable" states, etc.).
 */
export class DeployConfigError extends Error {
    constructor(message) {
        super(message);
        this.name = "DeployConfigError";
    }
}
export class EdkValidationError extends Error {
    constructor(message, options) {
        super(message, options);
        this.name = "EdkValidationError";
    }
}
export class DeployError extends Error {
    status;
    body;
    constructor(message, status, body, options) {
        super(message, options);
        this.status = status;
        this.body = body;
        this.name = "DeployError";
    }
}
/**
 * Thrown by `.deploy()` when an entity's source hash differs from the
 * recorded state hash and the backend has no PUT path for the entity's
 * kind. Skills (hydra) and flows (wolverine) currently sit here.
 *
 * Carries the recorded `id` (e.g. `skillId`, `flowId`) so the operator
 * can find the entity on the platform, delete it, and re-run. Once the
 * backend ships PUT for the kind, the EDK side wires a `doUpdate`
 * closure and this error stops firing.
 */
export class DeployUpdateUnsupportedError extends Error {
    entityKind;
    entityName;
    recordedId;
    constructor(entityKind, entityName, recordedId) {
        super(`Cannot update ${entityKind} "${entityName}": the source changed, ` +
            `but the platform has no PUT endpoint for this kind yet. The recorded ` +
            `id is "${recordedId}". Delete the entity on the platform, then re-run ` +
            `the deploy to create a fresh one.`);
        this.entityKind = entityKind;
        this.entityName = entityName;
        this.recordedId = recordedId;
        this.name = "DeployUpdateUnsupportedError";
    }
}
/**
 * Thrown when `.edk-state/<appId>.json` exists but does not parse to
 * the supported schema (missing fields, wrong version, malformed JSON).
 *
 * The SDK refuses to overwrite or "silently rebuild" the file because
 * that would mask the underlying problem — e.g. someone hand-edited
 * the file, a half-written file from a crashed deploy, or a downgrade
 * to an older SDK that wrote an incompatible schema.
 *
 * Recovery: run `edk generate --aspect-id <UUID>`
 * to regenerate state from server, or delete the file and re-run if the
 * cohort is empty on the platform.
 */
export class DeployStateCorruptError extends Error {
    statePath;
    constructor(statePath, detail, options) {
        super(`EDK state file at "${statePath}" is unreadable: ${detail}. ` +
            `Run "edk generate --aspect-id <UUID>" ` +
            `to regenerate it from the server, or delete the file if the app has ` +
            `no deployed entities on the platform.`, options);
        this.statePath = statePath;
        this.name = "DeployStateCorruptError";
    }
}
